head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataMap > M > undo]<br/>DataMap 모듈에 정의된 전체 Key 의 값(Value)과 상태값을 원본값(Origin Value)으로 복원합니다.",
    "validation" : [        
        "Key 의 '변경여부' 상태값은 false 로 설정됩니다.",
        "원본값(Origin Value)은 Key 에 최초로 할당된 데이터를 의미하며 이때 Key 의 '변경여부' 상태값은 false 입니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }    

    if (typeof input1 !== 'undefined') {
        input1.remove();
    }    

    // target 생성
    $c.gcm.createBasicDataMap();

    // input 생성
    $c.gcm.createEmptyInput('ref="data:target1.key1" style="width:200px;"', '', 'input1');

    scwin.btn_set_onclick();
    scwin.btn_getJSON_onclick();
}



scwin.btn_set_onclick = function (e) {
    target1.set("key1", "change1");
    target1.set("key2", "change2");
    // target1.set("key3", "change3");
    // target1.set("key4", "change4");
}



scwin.btn_getJSON_onclick = function (e) {
    let rtn = target1.getJSON();
    let jsonString = JSON.stringify(rtn);

    wf_body_bottom.getObj("scwin").setReturnValue("getJSON : " + jsonString);  
};



scwin.btn_undo_onclick = function (e) {
	target1.undo();

    scwin.btn_getJSON_onclick();
};
